-- 2302 🏋️ Exercises from the book "beat-the-press-with-a-box-midfield-build-up-play-and-sessions-from-guardiola-alo" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'beat-the-press-with-a-box-midfield-build-up-play-and-sessions-from-guardiola-alo');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Box midfield turn-or-recycle decision pattern', 'passing_opposed', 'passive', 'in_possession', 55, 56, 'Session 1: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Box midfielders read whether a lone presser closes them down and choose to turn forward or play back/sideways to break the lines.', 'Area split into two halves, a group of blues (GK, two defensive mids, attacking mid, forward) starting at each end; mannequins mark the first and third pressing lines and one red sits in the second line in each half.', 'GK plays to the left defensive mid. If the red steps up to press, he lays it to the other defensive mid who finds the attacking mid behind the red; the AM combines one-two with the forward round a mannequin and passes to the GK of the other group. If not pressed, the DM turns and plays the AM directly or via the forward as a link, the forward runs between the mannequins onto the AM''s through ball and passes on to the far group.', 'Red only presses or holds (semi-active). Rotate GK -> LDM -> RDM -> AM -> F -> GK of the other group.', 'Variation 2: a centre back replaces the right defensive mid; if the DM is pressed he returns it to the GK, who goes to the CB, CB to AM; if not pressed the DM turns and plays AM directly or via the forward. Rotation GK -> CB -> DM -> AM -> F -> other GK.', 'Scan early to decide turn or pass back; talk (''turn'', ''pass'', ''man on''); move the ball fast to use the space; time support runs to offer clear options.', '2 groups of 5 blues (incl. GK) + 2 semi-active reds', 10, 14, NULL, NULL, NULL, NULL, false, true, true, NULL, 10),
  ('Break lines vs two pressing midfielders 7+GK v 2', 'phase_of_play', 'opposed', 'in_possession', 57, 58, 'Session 1: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Build up through the box midfield by reading the reaction of the nearest opposing midfielder, receiving on the half turn or recycling to find the free player behind the second line.', 'Half pitch: blue GK, 2 centre backs (3 at the back with GK), a 4-man box midfield and a forward against 2 red central midfielders; mannequins stand in for the rest of the red defensive shape, with 3 mini goals on the far line.', 'GK circulates with the centre backs then passes into a defensive mid, who scans before receiving. If the nearest red holds, the DM receives on the half turn and plays forward, teammates forming triangles/diamonds; e.g. the forward plays a give-and-go with the attacking mid who runs in behind the line and scores.', 'Attack finishes by scoring in the mini goals after breaking the lines.', 'Variation 2: the red midfielder presses the receiving DM as soon as GK passes, so turning is off; the DM chooses quickly between the other DM, back to GK or a centre back, then the ball is moved fast into the space behind the presser to the attacking mid (option 1 via the other DM as link, option 2 via a centre back as link), who sets the forward to score. Can be adapted to a 2-at-the-back box with GK wider and one CB central.', 'Spot the press early and decide fast to turn or pass; clear calls (''turn'', ''pass''); move the ball quickly into space behind the press; sharp combinations through the lines.', '7 (+GK) v 2', 10, 10, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Box midfield 9v6 break-the-lines game', 'positional_game', 'opposed', 'in_possession', 59, 60, 'Session 1: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Build out from the keeper with a box midfield and decide whether to turn, pass back or play through the second pressing line.', 'Front part of the pitch with a big goal at each end; mannequins mark the reds'' third line. A yellow zone between the lines is where three blue attackers start; reds in a 4-2 shape can only enter it once a blue receives there.', 'GK circulates with the centre backs, then finds the defensive midfielder behind the first line; he turns or passes depending on whether the nearest red midfielder presses, and blues try to break the second line and finish.', 'Reds who win the ball counter to score within 8-12 seconds.', 'Variation 2: GK dribbles forward and draws the red forwards inward, freeing a centre back who reads the midfielders'' reactions and plays straight into the No.10 or through link players before playing in behind; can be set up as 3-at-the-back or 2-at-the-back (GK wider, one centre back central, but GK loses the dribble option).', 'Recognise pressure and choose turn, back pass or switch; move the ball quickly to use space behind the pressing lines.', '9 (+GK) v 6', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Three-zone 11v11 turn, recycle or dribble', 'conditioned_game', 'opposed', 'in_possession', 61, 61, 'Session 1: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Decision making under pressure to find an attacking midfielder behind the second pressing line.', '11v11 on three-quarters of a pitch; a yellow middle zone between the lines is only a visual guide with no restrictions.', 'Blues build from the GK, look for No.10 or No.11 behind the second line and then progress past the third line to score; players read the reds'' defending to decide whether to turn, recycle or dribble forward into space, and stay alert to the GK dribbling forward to free the centre backs.', 'Reds press high straight after the GK''s first pass and counter to score within 12 seconds when they win it.', 'Can be played with a 3-at-the-back or 2-at-the-back box midfield (GK wider, one centre back central).', NULL, '11v11', 22, 22, '3/4 pitch', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Keeper long pass to midfielder, play in behind', 'combination', 'passive', 'in_possession', 70, 72, 'Session 2: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Improve the attacking midfielder''s decision to receive and turn or play first time into space when a defender steps up.', 'Two keepers in the build-up half with a big goal at the far end marked into corners by poles; two 5-metre target squares for the attacking midfielders; blue players queue at the centre back and winger spots, with red defenders (or coaches) as full backs or centre backs.', 'Centre back passes to GK2, who finds a defensive midfielder, who sets it back to GK1; GK1 hits a 25-35 m diagonal into the attacking midfielder in a target square. If the nearby red defender presses he plays first time (or heads) in behind for the winger or forward to run on and finish; if the defender holds he turns and plays forward for a timed run.', 'Shots aimed at the corners between the poles; players rotate positions after each go.', 'Var 1: full back presses, first-time pass for the right winger. Var 2: full back holds, LAM turns and plays the left winger in. Var 3: defenders are centre backs; one presses and RAM plays first time for a forward. Var 4: centre back holds, LAM turns and finds a forward.', 'Accurate keeper passes into the squares; finishing in the corners; quick decisions; verbal cues; high tempo.', 'about 12 + 2 GKs + 2 red defenders', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Keeper over second line, target zones 7v4', 'phase_of_play', 'opposed', 'in_possession', 73, 74, 'Session 2: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Keeper plays over the second pressing line to an attacking midfielder who decides to turn or play first time in behind.', 'Half-plus pitch with a big goal; three 5x5 m target zones beyond the reds'' line; two small counter goals in the build-up half; mannequins as the first and middle lines; coaches act as feeders out wide.', 'Coach and the three at the back circulate until the GK plays forward into an attacking midfielder arriving in a target zone; if free he turns and a 5v4 attack follows, if a red defender steps up he plays first time in behind.', 'Blues score within 8 seconds; reds who win the ball counter on the two small goals within 8 seconds.', 'Var 2: 2-at-the-back box midfield (GK and one centre back deepest), a left winger added and the left back/one centre back area removed: 6+GK v 4+GK.', 'Accurate keeper delivery into the zones; scan before receiving; quick decision to turn or play first time; fast accurate finishing.', '7+GK v 4+GK', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Keeper over second line 10v8 with zones', 'phase_of_play', 'opposed', 'in_possession', 75, 76, 'Session 2: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Same aim as the previous practice but against four defenders and four pressing midfielders.', 'Larger part of the pitch with a big goal; three target zones behind the red midfield line; two mannequins as the first pressing line.', 'The back three circulate until the GK plays forward; if passed short behind the mannequins players turn, play forward or recycle; if the GK goes long into a target zone the receiver reads the defender and either turns or plays first time in behind for a runner.', 'Reds win it and counter by dribbling past the red line, receiving beyond it, or scoring in the goal.', 'Var 2: 2-at-the-back box midfield, left back pushed up as a normal left winger; e.g. pressed No.8 heads into space for No.11, who crosses for the other attacking midfielder at the back post.', 'Same as earlier practices in the session.', '10 (+GK) v 8', 19, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Keeper over pressing lines 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 77, 77, 'Session 2: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Apply the keeper''s choices (behind the first line, over or through the second) in a full game.', '11v11 starting with the blue GK; 2-at-the-back box midfield shape.', 'Reds press hard after the first pass; the blues build from the back and the attacking midfielders read whether a defender steps up to choose turn or first-time ball in behind.', 'A goal scored after a long pass to an attacking midfielder counts double; reds counter within 10-12 seconds.', 'Can be adapted to 3-at-the-back.', 'Same as earlier practices in the session.', '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Find the free player 2v2+2 possession', 'possession', 'opposed', 'in_possession', 87, 88, 'Session 3: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Quickly read passing options and use the numerical advantage to find the free player.', '12 x 18 m area (adjust for age/level) with small goals at each end; 2v2 inside with an extra blue on the outside at each end; coach with balls on the side.', 'Coach feeds an outside blue who enters to make an overload; the nearest red must press, and the blues find the free player directly or via a link player, who passes to the outside player at the far end; the passer rotates out and the outside player enters to go the other way.', 'Reds who win it score in either of the two small goals at that end.', 'Part 2: continuous play with rotations at the opposite end.', 'Read the situation fast; diamond shape to open lanes; smart decisions to reach the free man; quick combinations; high tempo.', '2v2 + 2 outside', 6, 6, '12 x 18 m', 18.0, 12.0, NULL, true, false, true, NULL, 90),
  ('4v3 overload three-team three-zone game', 'small_sided_game', 'opposed', 'in_possession', 89, 89, 'Session 3: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Create and exploit 2v1 and 3v2 overloads by finding and moving the ball to the free player.', 'Zone 1 25 x 42 m split into halves, Zone 2 25 x 10 m, Zone 3 25 x 7 m with a goal and GK; two small goals at the start end. Blue and yellow attack, red defend; yellows start outside.', 'Start 1v1 in each half of Zone 1 and 1v1 in Zone 2; a yellow dribbles in to make 2v1, attackers find the free player, who dribbles into Zone 2 (2v1) and passes into Zone 3 to score against the keeper.', 'After the first pass everyone moves freely but defenders cannot enter Zone 3; after each attack the finisher goes out and others move up a position; defending team swaps after a set time; reds who win it score in a small goal.', NULL, NULL, '3 teams', NULL, NULL, 'Zone 1 25 x 42 m', 38.4, 22.9, NULL, true, true, true, NULL, 100),
  ('Split-pitch strong side game 2-at-back', 'phase_of_play', 'opposed', 'in_possession', 90, 90, 'Session 3: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Build with a 4v3 numerical advantage on the strong side and find the free attacking midfielder.', 'Three-quarters of a pitch split into two halves by a 5 m vertical zone, two goals with keepers at the build-up end and a big goal at the other; reds in a combined 4-4-2 (2-2-1 per half).', 'Left half 6+GK v 5+GK: blues find the free attacking midfielder and score. Right half 5(+GK) v 5: GK2 acts as a centre back to draw the red forward and open forward lanes; the left centre back joins after the first pass for balance.', 'Reds who win the ball on either side counter within 10-12 seconds; reset after each phase.', NULL, NULL, '11 + 2 GKs v 10 + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Split-pitch strong side game 3-at-back', 'phase_of_play', 'opposed', 'in_possession', 91, 92, 'Session 3: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'With a 3-at-the-back box midfield, read where the overload is and exploit it.', 'Same split pitch with a 5 m yellow middle zone and two build-up goals; the No.10 stands in the middle zone.', 'No.10 moves left or right to decide which side has the overload. Var 1: 4v4 on the left (play through the press, left back attacks the flank without a winger) and 6+GK v 5+GK on the right (4v3, find the free No.6).', 'Reds counter within 10-12 seconds after a win.', 'Var 2: No.10 shifts left so the left becomes 6v5 overload and the right 5v5 equality; can use two No.10s alternating.', 'Quick reading of the situation; support play into lanes; fast combinations; high tempo.', '11 + 2 GKs v 10 + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Strong side overload 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 93, 93, 'Session 3: Practice 5', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Exploit the numerical advantage on the strong side in a full game.', '11v11 on three-quarters of a pitch; play always restarts with the blue GK.', 'Blues build from the GK and look to create and use a 4v3 overload on one side to find the free player before attacking the goal.', 'Goal = 1, goal after exploiting the strong-side overload = 2; reds win and counter; swap roles after a set time.', NULL, 'Read the situation and keep lanes open; smart decisions; fast combinations; high tempo.', '11v11', 22, 22, '3/4 pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Box midfield combinations and switch to target zones', 'passing_unopposed', 'unopposed', 'in_possession', 105, 106, 'Session 4: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Rehearse box-midfield combinations that break lines and finish with a long switch.', '40 x 60 m split into two halves, an 8 x 5 m target area on each side and mannequins as opponents; the pattern runs in both halves at once.', 'Var 1: A dribbles out of the target zone to B; B plays a one-two with C, then finds D, who takes a forward touch to E, gets it back and switches long into the opposite target zone for the next player.', 'Rotation A1-B1-C1-D1-E1-A2-B2-C2-D2-E2-A1.', 'Var 2: A to B to C; C goes forward and picks E or D; if E receives he lays off to D, who switches.', 'Quick purposeful combinations; accurate short and long passing; high tempo, sharp movement.', '10+', 10, NULL, '40 x 60 m', 54.9, 36.6, NULL, false, false, true, NULL, 140),
  ('Equal numbers switch-play 3-team game', 'small_sided_game', 'opposed', 'in_possession', 107, 108, 'Session 4: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Build with equal numbers and switch play into a new area when the strong side is closed.', 'Two 25 x 15 m areas, each with small goals; teams of 4 (blue, red, yellow); yellows act as outside support (centre back, full back, winger, attacking midfielder roles); coaches with balls.', 'Coach feeds a blue who dribbles in for 4v4 versus reds, trying to score in two small goals or find an outside yellow, who switches into the other area where outside players sprint in; after a goal or switch reds transition to defend the second area, two blues go outside and the yellows attack, able to switch back to the blues.', 'All yellows must touch the ball before scoring; attackers must finish within a set time or become defenders; reds counter to the other two goals; ball out = coach restart.', NULL, 'Off-ball movement; supporting players adjust; fast combinations; quality long passes with support; high speed of play.', '12 in 3 teams of 4', 12, 12, '2 x 25 x 15 m', 22.9, 13.7, NULL, true, false, true, NULL, 150),
  ('Split-pitch equal numbers build-up game', 'phase_of_play', 'opposed', 'in_possession', 109, 110, 'Session 4: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Beat a press with equal numbers through short combinations or long balls and second-ball support.', 'Pitch split into two halves by a middle strip, two build-up goals with keepers and big goal at the far end; both sides active at once.', 'Var 1 (2-at-the-back): right side 5(+GK) v 6(+GK) with the GK as a centre back and the centre back entering after the first pass; left side 6(+GK) v 6(+GK). Blues combine short or play long and support the second ball to play in behind and score.', 'Reds counter within 10-12 seconds on a win.', 'Var 2: 3-at-the-back shape, 5v5 on the left and 6v6 on the right; reds press hard after the first pass.', 'Timed off-ball movement; create lanes between and beyond lines; quick combinations under pressure; long pass with fast support; high intensity.', '11 + 2 GKs v 11 + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Three-zone 11v11 equal numbers game', 'conditioned_game', 'opposed', 'in_possession', 111, 112, 'Session 4: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal) build-up patterns', 'Recognise overload, equality or switching chance and pick the right build-up option.', 'Three-quarters pitch; a 7 m central vertical strip splits it into left and right zones.', 'GK passes into one wide zone; with a 4v3 on that side blues use quick combinations to find the free player before scoring. Var 2: reds shift early to equal numbers, so blues continue combining, go long with support, or switch to the weak side.', 'Reds may only press after the GK''s first pass; reds counter within 10-12 seconds.', 'Remove the visual zones so players play naturally; works with 2- or 3-at-the-back.', 'React quickly; verbal cues; offer options; accurate, aware switches; high tempo.', '11v11', 22, 22, '3/4 pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Box midfield combinations past a double pivot', 'passing_unopposed', 'unopposed', 'in_possession', 125, 125, 'Session 5: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Build-up pattern from the goalkeeper through a box midfield when the opponent''s No.10 has to cover both deeper midfielders.', 'Half pitch with GK, two wide players (B1/B2) at mannequin-marked wide spots, a box midfield (LDM, RDM, LAM, RAM) and starters A1/A2 by two small goals at halfway; 3 red mannequins form a double-pivot midfield (e.g. 4-2-3-1).', 'A1 plays to B1, who returns to the GK while the deep midfielders drop wider and the attacking midfielders push up. GK finds RDM, who turns and plays RAM; RAM drops and lays back across to LDM, who plays LAM, and LAM finishes into a small goal. Next run starts from A2 to B2 on the other side.', 'Players rotate A1 -> B1 -> LDM -> RDM -> RAM -> LAM -> A2.', 'Alternative route shown where the ball goes through the other midfielders.', NULL, 'GK + 8 players', 9, 12, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('GK long pass and box support vs single pivot', 'passing_unopposed', 'unopposed', 'in_possession', 126, 126, 'Session 5: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Goalkeeper''s aerial pass to an attacking midfielder and support play around a lone holding midfielder covering two players.', 'Same half-pitch set-up as Practice 1, but the mannequins now show a single-pivot midfield (e.g. 4-3-3) with one man between LAM and RAM.', 'A1 to B1 to GK while the deep midfielders drop and the attacking midfielders go wider. GK lofts a ball to RAM, who sets it back to the onrushing RDM; RDM plays diagonally forward to LAM, who dribbles on and scores in a small goal. Repeat from A2/B2 on the other side.', 'Rotation A1 -> B1 -> LDM -> RDM -> RAM -> LAM -> A2.', NULL, 'Widen the gap from the mannequin covering two players; synchronise off-ball movement to open midfield lanes.', 'GK + 8 players', 9, 12, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Find the free midfielder 6v4 (3 at back)', 'positional_game', 'overload', 'in_possession', 127, 127, 'Session 5: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Build up from a 3-at-the-back box midfield against a man-marking high press and find the unmarked midfielder.', 'Area from the goal line to beyond halfway with two small goals at the far end; blues = GK, 2 centre backs and box midfield (6+GK), reds press with 4 inside plus a winger who waits outside.', 'GK starts; the red winger joins after the first pass. Reds play a double pivot so their No.10 must mark both blue deep midfielders; blues push those two wider and the attacking midfielders higher to stretch them, then find the free deep midfielder and progress to score in the small goals.', 'Reds: win the ball and counter to score within 8-12 seconds.', 'Alternate the red midfield between a single and a double pivot.', 'Movement and timing open lanes; read the press, decide fast, play accurate line-breaking passes.', '6 (+GK) v 4 (+1)', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Find the free midfielder 5v4 (2 at back)', 'positional_game', 'overload', 'in_possession', 128, 128, 'Session 5: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Same build-up problem with a 2-at-the-back box midfield against a single-pivot man-marking press.', 'As Practice 3 but blues have GK, one centre back and a box midfield (5+GK) against 4 reds, small goals at the far end.', 'The lone red pivot must cover both blue attacking midfielders, so they spread wider while the deep midfielders drop centrally to make room. Blues find the free attacking midfielder (often via GK pass) and progress to score.', 'Reds win the ball and counter to score within 8-12 seconds.', 'Alternate single and double pivot for the reds.', 'Movement and timing create lanes; read the press, quick decisions, accurate line-breaking passes.', '5 (+GK) v 4', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Find the free midfielder 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 129, 129, 'Session 5: Practice 5', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Apply the session''s box-midfield principles in a full game against a high press with zonal defending and midfield man marking.', 'Full pitch 11v11; blues build up from GK with a 2- or 3-at-the-back box midfield.', 'Reds press high after the first pass and man-mark in midfield. Blues use the box midfield to find the free player; e.g. against a single pivot the GK plays aerial passes to the attacking midfielders, who stretch away from the red pivot trying to cover both.', NULL, 'Alternate single or double pivot for the reds.', 'Make distance from the midfielder marking two; coordinated movements; spot pressing triggers early and decide quickly.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Passing pattern to free player via link', 'passing_opposed', 'passive', 'in_possession', 142, 142, 'Session 6: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Rehearse moving the ball past a presser to the free player using a dropping link player.', 'Two 10 x 25 m channels side by side, run simultaneously; in each, starters A1 and A2 at opposite ends, free player B, link player C and pressing players D at each end.', 'A1 dribbles in, D1 presses to block the lane to B1; A1 plays the dropping C1, who finds B1. B1 dribbles and plays A2 while C1 runs to the far end to become the presser D2. A2 dribbles, D2 presses to block B2, so A2 plays B1 (now the link) who sets B2, and B2 dribbles to the start. Roles shift each run.', 'Rotations: bottom A1 -> B1 -> C2 -> D1 -> A1; top A2 -> B2 -> C1 -> D2 -> A2.', NULL, NULL, '2 groups of about 6-8', 12, 16, '10 x 25 m (x2)', 25.0, 10.0, NULL, false, false, true, NULL, 230),
  ('Link player 3v2 continuous waves', 'one_v_one', 'overload', 'in_possession', 143, 144, 'Session 6: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Create and exploit a 3v2 by moving the ball to the unmarked player directly or through a link player.', '10 x 20 m area split into two halves with a 1v1 in each (2v2), two small goals at each end, plus 3 extra blues waiting outside.', 'A dribbles in to make 3v2; the nearest red steps to press A, leaving C free. A plays C directly or via link player B; C scores in either small goal and exits to an outside spot. D then dribbles in from the other end to start a new 3v2 the other way, with the new free player and link player.', 'Reds win the ball and counter to score within 10-12 seconds; red defenders rotate out after a set number of reps.', 'Phase 1 single wave, phase 2 continuous end-to-end waves.', 'Use the link player; synchronised movement; quick, accurate passing; decide from the press; high tempo.', '3v2 waves (about 7-9 players)', 7, 10, '10 x 20 m', 20.0, 10.0, NULL, true, false, true, NULL, 240),
  ('Free player or link, finish 3v2 (+GK)', 'finishing', 'overload', 'in_possession', 145, 145, 'Session 6: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Find the free player against a presser and finish on a big goal.', '10 x 20 m area with a 2v2 (1v1 per half) and 3 extra blues outside; a 5 m finishing zone in front of a full goal with GK at one end, two small goals at the other.', 'A dribbles in for a 3v2; the nearest red presses A. Blues find the free player (B) directly or through link player C; he receives in or dribbles into the finishing zone and shoots. The shooter goes to the start and a new blue dribbles in.', 'Reds cannot enter the finishing zone; reds win the ball and counter into the 2 small goals; reds rotate after a set number of reps.', 'Add more outside blue players.', NULL, '3v2 (+GK) with extra blues', 8, 10, '10 x 20 m + 5 m finishing zone', 25.0, 10.0, NULL, true, true, true, NULL, 250),
  ('Beat ultra-aggressive press 8+1 v 7', 'phase_of_play', 'overload', 'in_possession', 146, 146, 'Session 6: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Build up with a 3-at-the-back box midfield against a press that goes right onto the goalkeeper with man marking.', 'Own half to beyond halfway, full goal with GK, two small goals at the far end; blues 8 + GK plus an outside forward (No.9) v 7 reds (10v7 overall).', 'Blues progress from the GK, find the free player directly or via a link player and score in a small goal; reds man-mark across the area to force them into finding that player, then counter.', 'A red must press the GK immediately; blue No.9 is limited to one-touch passes back into the area; coach restarts with a pass to reds when the ball goes out; reds counter to score within 8-10 seconds.', NULL, 'Quick decisions, circulation and positioning to break the press.', '8+1 (+GK) v 7', 17, 17, 'half pitch+', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Beat ultra-aggressive press 7+1 v 6', 'phase_of_play', 'overload', 'in_possession', 147, 147, 'Session 6: Practice 5', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Same problem with a 2-at-the-back box midfield (GK + one centre back).', 'As Practice 4, blues 7 + GK plus outside forward (9v6 overall) v 6 reds, two small goals to attack.', 'Blues identify the free player and move the ball to him against the press up to the GK, using link players (e.g. No.2) to bypass pressure, then score in a small goal.', 'Same rules and restrictions as Practice 4.', NULL, 'Link players follow the link-player principles (timing, angle, scanning).', '7+1 (+GK) v 6', 15, 15, 'half pitch+', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Free player vs ultra press 11v11', 'conditioned_game', 'opposed', 'in_possession', 148, 148, 'Session 6: Practice 6', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Full-game build-up against man-marking pressing up to the goalkeeper with a 3-at-the-back box midfield.', 'Full pitch 11v11.', 'Reds press right up to the GK with man marking. Blues build up and score; finding the free player with a direct pass or via a link before scoring doubles the goal. Every restart is from the blue GK.', 'Goal = 1, goal after freeing the free player = 2; reds win it and counter; roles swap after a set time.', NULL, 'Synchronised off-ball movement; quick accurate passing into gaps; choose link player or direct option under pressure; apply link-player principles.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Support zones vs man marking circuit', 'passing_opposed', 'opposed', 'in_possession', 158, 158, 'Session 7: Practice 1', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Find the free player against tight man marking by moving into support zones and using a link player.', 'Run on both sides at once; each side has one low zone (8 x 5 m) and two larger zones (8 x 8 m) with a red marker in each zone, blues A-F around them.', 'A passes to B, who plays it diagonally back to C. C dribbles from zone 1 into zone 2, drawing the red; D moves into a lane to be free while E mirrors on the other side, giving C two options. C plays D directly or via link player E; D dribbles into zone 3 and E offers again, and the ball finds the free player (E or F) and back to the start.', 'Blues: completed circuit = 1 point; reds: win the ball or force a mistake = 1 point. Players rotate positions.', NULL, NULL, 'about 12-16 (two groups)', 12, 16, 'zones 8 x 5 m and 8 x 8 m', NULL, NULL, NULL, false, false, true, NULL, 290),
  ('Long pass and support runs combination', 'combination', 'unopposed', 'in_possession', 159, 159, 'Session 7: Practice 2', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Rehearse beating a man-marking press with a long pass to a target and well-timed support runs.', 'Two halves run at once, each with a small goal at each end and mannequin positions; roles A1 long passer, B receiver, C creates space, D exploits space.', 'Left side: C drops as if to pull his marker away and D runs into the vacated space. A1 drives a long pass to B, who sets D on the move; D dribbles, scores in the small goal and goes to A2. Right side: C drops while D overlaps into the space, receives and finishes.', 'Rotation A1 -> B -> C -> D -> A2; then repeat the other way.', NULL, 'Well-timed movement to disturb markers; accurate short and long passing.', '2 groups of 5-6', 10, 12, 'half pitch split in two', NULL, NULL, NULL, true, false, true, NULL, 300),
  ('Box midfield vs man press half pitch', 'phase_of_play', 'opposed', 'in_possession', 160, 161, 'Session 7: Practice 3', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Beat an ultra-aggressive man-marking press with a box midfield and link players.', 'Low half of the pitch, full goal with GK, two small goals at halfway; 7 (+GK) v 7 with a 2-at-the-back box midfield (wingers and forward not involved).', 'Reds press up to the GK with man marking. Blues find the free player, use any overload to break forward and score in either small goal; reds win it and counter.', 'Reds counter to score within 10-12 seconds.', 'Variation 2: 3-at-the-back box midfield, 8 (+GK) v 8, all players man-marked.', 'Smart movement to lose markers; timed, synchronised runs; well-weighted passing; read pressing cues; link-player principles.', '7 (+GK) v 7; 8 (+GK) v 8', 15, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('GK long pass vs man press 7v7', 'small_sided_game', 'opposed', 'in_possession', 162, 163, 'Session 7: Practice 4', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Create and use space behind a full-pitch man-marking press with the goalkeeper''s long pass.', '7v7 (+GKs) over most of the pitch; blue GK and full goal at one end, two small goals plus a red GK goal at the other; blues set up with a box midfield, left back, right winger and forward (3 at back version), centre backs and right back not involved.', 'Coach passes to the blue GK. Blues move off the ball to open space and the GK plays long to the forward (No.9) or left back (No.3) to score; reds press man-to-man and counter to the small goals.', 'Reds counter to score within 10-12 seconds. Variation 2: GK must play within 4-5 seconds of receiving.', 'Variation 2: 2-at-the-back box midfield (left back removed, left winger added), long pass to the target forward who is supported.', NULL, '7v7 (+GKs)', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Read pressing triggers 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 164, 164, 'Session 7: Practice 5', 'Guardiola (Man City), Alonso (Leverkusen), Arteta (Arsenal)', 'Recognise the type of press and choose the right build-up answer: free player against a press on the GK, or making space against a press on the first receiver.', '11v11 on three-quarters of a full pitch.', 'Reds use full-pitch man marking, alternating ultra-aggressive pressing up to the GK and high pressing on the first receiver. Blues adapt: find the free player against the former, coordinate movements to create and use space (e.g. long ball to target forward) against the latter, and score.', 'Reds win the ball and counter to score within 10-12 seconds.', NULL, NULL, '11v11', 22, 22, '3/4 pitch', NULL, NULL, NULL, true, true, true, NULL, 330)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'beat-the-press-with-a-box-midfield-build-up-play-and-sessions-from-guardiola-alo') b;
